<script setup lang="ts">
// 题目产出详情主体（共享）：题面上下文 + 状态 + 五类最新产出（含内部）+ 版本历史 + 调用账本。
// 独立详情页与抽屉外壳共用，避免两处维护同一份渲染逻辑。
import { computed, nextTick, onBeforeUnmount, ref, watch } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, type GlobalProperties } from "@/util/tips";
import { GetEnrichDetail } from "@/apis/problem-enrichment";
import echarts, { type EChartsOption } from "@/util/echarts";
import {
  callStatusText,
  callStatusTheme,
  fmtSec,
  fmtTime,
  stageText,
  stateStatusText,
  stateStatusTheme,
  taskTypeText,
  visibilityText,
} from "./enrich-common";
import EnrichPipelineSteps from "./EnrichPipelineSteps.vue";
import AnnotationCard from "./AnnotationCard.vue";
import type {
  EnrichDetailAnnotation,
  EnrichDetailHistory,
  EnrichProblemDetail,
} from "@/types/problem-enrichment";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { handleGotoProblem } from "@/util/router";

const props = defineProps<{
  problemId: number;
  problemKey?: string; // 详情页 path 路由场景用 key 加载（可读 URL）；缺省时按 id 加载
  dataVersion: number; // 外部动作（重判/人工定稿）后递增，自动刷新
  active: boolean; // 抽屉可见或页面挂载时为 true，触发首次加载
}>();

const emit = defineEmits<{
  (e: "requeue", problemId: number): void;
  (e: "loaded", problem: { key?: string; title?: string } | undefined): void;
}>();

const globalProperties = useCurrentInstance().globalProperties as GlobalProperties;
const { isMobile } = useBreakpoint();

const loading = ref(false);
const detail = ref<EnrichProblemDetail | null>(null);
const statementOpen = ref(false);
const callsOpen = ref(false);

// 操作统一用后端下发的真实 problem_id，与 URL 里的 key 解耦
const realProblemId = () => detail.value?.state?.problem_id || props.problemId;

// AI 审阅总进度（五阶段完成度；进行中的阶段单列提示，消除「卡死」错觉）
const doneSteps = computed(() => (detail.value?.steps ?? []).filter((s) => s.status === "success").length);
const totalSteps = computed(() => (detail.value?.steps ?? []).length);
const progressPercent = computed(() =>
  totalSteps.value ? Math.round((doneSteps.value / totalSteps.value) * 100) : 0
);
const runningStage = computed(() => {
  const s = (detail.value?.steps ?? []).find((x) => x.status === "running");
  return s ? stageText[s.stage] || s.stage : "";
});
// 难度雷达图容器。注意：卡片在 v-for 里渲染，模板 ref 会被 Vue 收集成数组，
// 不能直接用 ref="radarRef"（历史事故：echarts.init 收到数组报 getContext is not a function，
// 详情抽屉每次打开带难度卡都会弹「加载失败」）。改用函数式 ref 存单元素。
const radarRef = ref<HTMLElement | null>(null);
const setRadarRef = (el: unknown) => {
  radarRef.value = (el as HTMLElement) ?? null;
};
let radarChart: ReturnType<typeof echarts.init> | null = null;

// ── 历史评价切换 ──
// 设计决策（2026-10）：历史版本原先在每张卡片下用折叠面板铺开，每一版都以完整卡片渲染，
// 五类堆在一起页面很长，也没法把某一版和当前版对照着看。改为「主区仍一屏看全五类产出 +
// 右侧栏按类型列出全部版本，点某版就把对应卡片切到该版」——与「AI 生成测试数据」页
// （主区工作台 + 右侧历史任务列表）同一套交互口径。每类产出的选中项各自独立，
// 切换某一类不会动其余卡片；移动端没有右侧栏，等价入口是卡片头部的版本选择器。
type VersionView = {
  id: number; // 当前行 id 或历史行 id
  isCurrent: boolean;
  source: string;
  review_status: string;
  confidence: number;
  insert_time: string;
  visibility: string; // 只有当前行带可见性分级，历史行不落该字段
  payload: Record<string, unknown>;
};

const currentVersion = (a: EnrichDetailAnnotation): VersionView => ({
  id: a.id,
  isCurrent: true,
  source: a.source,
  review_status: a.review_status,
  confidence: a.confidence,
  insert_time: a.insert_time,
  visibility: a.visibility,
  payload: a.payload ?? {},
});

const historyVersion = (h: EnrichDetailHistory): VersionView => ({
  id: h.id,
  isCurrent: false,
  source: h.source,
  review_status: h.review_status,
  confidence: h.confidence,
  insert_time: h.insert_time,
  visibility: "",
  payload: h.payload ?? {},
});

// 版本列表按「新→旧」：当前行排最前，历史行后端给的是「旧→新」，这里反转，
// 与右侧栏「越靠上越新」的阅读习惯一致，也与历史任务列表同向。
const versionsOf = (a: EnrichDetailAnnotation): VersionView[] => [
  currentVersion(a),
  ...[...(a.history ?? [])].reverse().map(historyVersion),
];

// 右侧栏的分组数据：一类产出一组，组内新→旧
const versionGroups = computed(() =>
  (detail.value?.annotations ?? []).map((a) => ({
    taskType: a.task_type,
    title: taskTypeText[a.task_type] || a.task_type,
    versions: versionsOf(a),
  }))
);

// 每类产出各自记「正在看哪一版」：值为历史行 id，0/缺省表示当前版本
const pickedHistory = ref<Record<string, number>>({});

// 该类当前展示的版本。选中项找不到时回落到当前版本——历史窗口只保留最近 3 版，
// 轮询刷新或重判后旧版本可能被挤出窗口，没有这层兜底就会渲染成空白。
const viewOf = (a: EnrichDetailAnnotation): VersionView => {
  const id = pickedHistory.value[a.task_type] ?? 0;
  const h = id ? (a.history ?? []).find((x) => x.id === id) : undefined;
  return h ? historyVersion(h) : currentVersion(a);
};

// 卡片 → 展示版本：模板里每处都调 viewOf(a) 会一屏算几十次，这里一次算好查表
const viewMap = computed<Record<string, VersionView>>(() => {
  const map: Record<string, VersionView> = {};
  for (const a of detail.value?.annotations ?? []) {
    map[a.task_type] = viewOf(a);
  }
  return map;
});

// 模板里读「某类产出正在展示的版本」的入口：卡片都来自 detail.annotations，查表必有值
const view = (a: EnrichDetailAnnotation): VersionView => viewMap.value[a.task_type];

// 难度雷达跟随所选版本（切到历史难度需要重画）
const difficultyView = computed<VersionView | null>(() => viewMap.value["difficulty"] ?? null);

// 卡片 DOM 引用：点右侧栏后主区对应卡片可能不在视口内，需要主动滚过去。
// 注意：卡片在 v-for 里渲染，模板 ref 会被收集成数组（历史事故见下方雷达图 ref），
// 故同样用 Map + 函数式 ref 按 task_type 存单个元素。
const cardRefs = new Map<string, HTMLElement>();
const setCardRef = (taskType: string) => (el: unknown) => {
  if (el) {
    cardRefs.set(taskType, el as HTMLElement);
  } else {
    cardRefs.delete(taskType);
  }
};

const pickVersion = (taskType: string, v: VersionView) => {
  pickedHistory.value = { ...pickedHistory.value, [taskType]: v.isCurrent ? 0 : v.id };
  // 桌面端点了右侧栏，主区对应卡片可能在视口外，不滚过去会有「点了没反应」的错觉；
  // 移动端是卡片内选择器，卡片本来就在眼前，无需滚动。
  if (!isMobile.value) {
    nextTick(() => cardRefs.get(taskType)?.scrollIntoView({ behavior: "smooth", block: "start" }));
  }
};

// 移动端卡片内的版本选择器：值就是当前展示版本的 id，选中即切到该版
const selectVersion = (a: EnrichDetailAnnotation, id: number) => {
  const v = versionsOf(a).find((x) => x.id === id);
  if (v) {
    pickVersion(a.task_type, v);
  }
};

// 版本列表时间（本地时区 MM-DD HH:mm）：与「AI 生成测试数据」的历史任务列表同一口径。
// 右侧栏很窄，完整的年月日会把标签挤到换行。
const fmtVersionTime = (s?: string): string => {
  if (!s) {
    return "";
  }
  const d = new Date(s);
  if (Number.isNaN(d.getTime())) {
    return "";
  }
  return d.toLocaleString("zh-CN", {
    hour12: false,
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
};

// 版本选项文案：当前版明确标注，历史版给时间 + 来源，窄选择器里也能分辨
const versionLabel = (v: VersionView): string =>
  v.isCurrent
    ? `当前版本 · ${fmtVersionTime(v.insert_time)}`
    : `${fmtVersionTime(v.insert_time)} · ${v.source === "human" ? "人工" : "AI"}`;

// 当前加载目标（详情页用 key、抽屉用 id）：用来区分「同一题刷新」与「换了一题」
const targetKey = () => (props.problemKey ? `key:${props.problemKey}` : `id:${props.problemId}`);
let loadedTarget = "";

// silent：轮询触发的后台刷新——不显示 loading 遮罩，也不重置用户已展开的区块。
// 否则每 5 秒闪一次加载态、并把题面/调用账本折叠回去（用户反馈的核心问题）。
const load = async (silent = false) => {
  if (!props.problemId && !props.problemKey) {
    return;
  }
  if (!silent) {
    loading.value = true;
  }
  try {
    // key 场景传 key（详情页 path 路由）；否则按 id 加载
    const res = await GetEnrichDetail(props.problemKey ? 0 : props.problemId, props.problemKey);
    if (res.code === 0) {
      const sameTarget = loadedTarget === targetKey();
      detail.value = res.data;
      // 只有换题才把展开状态归位；同一题的重判/轮询刷新保留用户的展开选择
      if (!sameTarget) {
        statementOpen.value = false;
        callsOpen.value = false;
        // 换题时版本选中态一并归位，避免把上一题的历史行 id 带到新题上
        pickedHistory.value = {};
      }
      loadedTarget = targetKey();
      emit("loaded", res.data.problem);
      // 轮询开关只依赖状态字段，先同步再渲染图表：图表初始化异常不该影响轮询判定
      syncPolling();
      await nextTick();
      renderRadar();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载题目产出详情失败");
  } finally {
    if (!silent) {
      loading.value = false;
    }
  }
};

// 难度雷达图（四维，1~5）；移动端隐藏不渲染。画的是当前展示的那一版难度（可能是历史版本）。
let radarSignature = ""; // 上一次画图的难度产出内容：内容没变就不重建，避免轮询时无谓闪烁
const renderRadar = () => {
  if (isMobile.value) {
    return;
  }
  const v = difficultyView.value;
  const dom = radarRef.value;
  if (!dom || !v) {
    return;
  }
  const signature = JSON.stringify(v.payload ?? {});
  if (radarChart && radarSignature === signature && radarChart.getDom() === dom) {
    return;
  }
  radarSignature = signature;
  if (radarChart) {
    radarChart.dispose();
    radarChart = null;
  }
  const p = v.payload as any;
  radarChart = echarts.init(dom, null, { renderer: "canvas" });
  // 轴标签色：canvas 不认识 CSS 变量，需从文档解析出实际色值（历史事故：写 var(--xxx) 导致标签不渲染）
  const axisColor =
    getComputedStyle(document.documentElement).getPropertyValue("--td-text-color-secondary").trim() || "#8a8a8a";
  const option: EChartsOption = {
    radar: {
      indicator: [
        { name: "思维", max: 5 },
        { name: "算法", max: 5 },
        { name: "实现", max: 5 },
        { name: "陷阱", max: 5 },
      ],
      // 半径与中心为轴名标签留出边缘空间（贴边会被 canvas 裁切）
      radius: "56%",
      center: ["50%", "54%"],
      splitNumber: 5,
      axisName: { color: axisColor, fontSize: 12 },
    },
    series: [
      {
        type: "radar",
        data: [
          {
            value: [p.thinking ?? 0, p.algorithm ?? 0, p.implementation ?? 0, p.pitfalls ?? 0],
            areaStyle: { opacity: 0.25 },
          },
        ],
      },
    ],
  };
  radarChart.setOption(option);
};

watch(
  () => [props.active, props.problemId, props.problemKey],
  () => {
    if (props.active && (props.problemId || props.problemKey)) {
      load();
    } else if (radarChart) {
      radarChart.dispose();
      radarChart = null;
    }
  },
  { immediate: true }
);

// 重判/人工定稿后仍打开时自动刷新详情
watch(
  () => props.dataVersion,
  () => {
    if (props.active && (props.problemId || props.problemKey)) {
      load();
    }
  }
);

// 切换版本后重画雷达（难度切到历史版本时图形要跟着变；renderRadar 内部按 payload 去重）
watch(pickedHistory, () => {
  if (props.active) {
    nextTick(() => renderRadar());
  }
});

// 重判：交给父组件执行（会刷新各视图），主体不关闭以便观察进度
const handleRejudge = () => {
  if (!detail.value?.state) {
    return;
  }
  emit("requeue", realProblemId());
};

const gotoProblem = () => {
  if (detail.value?.problem?.key) {
    handleGotoProblem(detail.value.problem.key);
  }
};

// ── 进行态自动轮询 ──
// 重判后题目进入排队/处理中，AI 每阶段需要数十秒；仅靠 dataVersion 触发的一次刷新
// 会让界面停在旧状态（用户反馈「重判后不刷新、看不到进度」）。
// 只在「排队(1)/处理中(2)」这两种进行态每 5 秒静默刷新（页面可见时），成功/失败后自动停止。
// 未处理(0) 属于静止态：它不会自己变，纳入轮询只会让详情页无差别每 5 秒重载一次
// （用户反馈「无论什么状态都会自动刷新」）。自动批量模式下被认领的存量题，
// 想看进度可点「重判」入队，或刷新页面。
let pollTimer: ReturnType<typeof setInterval> | null = null;
const syncPolling = () => {
  const status = detail.value?.state?.status;
  const needPoll = props.active && (status === 1 || status === 2);
  if (needPoll && !pollTimer) {
    pollTimer = setInterval(() => {
      if (document.visibilityState === "visible") {
        // 静默刷新：不动 loading、不折叠用户展开的区块
        load(true);
      }
    }, 5000);
  } else if (!needPoll && pollTimer) {
    clearInterval(pollTimer);
    pollTimer = null;
  }
};
onBeforeUnmount(() => {
  if (pollTimer) {
    clearInterval(pollTimer);
    pollTimer = null;
  }
});
</script>

<template>
  <t-loading :loading="loading">
    <template v-if="detail">
      <!-- 标题与操作 -->
      <div class="detail-head">
        <div class="detail-title-row">
          <h3 class="detail-title">
            #{{ detail.problem?.key || problemKey || problemId }} {{ detail.problem?.title ?? "" }}
          </h3>
          <t-button variant="outline" size="small" @click="gotoProblem">去题目页</t-button>
        </div>
        <t-space size="small" break-line>
          <t-tag
            v-if="detail.state"
            :theme="stateStatusTheme[detail.state.status]"
            variant="light"
          >
            {{ stateStatusText[detail.state.status] }}
          </t-tag>
          <EnrichPipelineSteps :steps="detail.steps ?? []" size="md" />
          <span v-if="detail.state" class="detail-meta">
            尝试 {{ detail.state.attempt }} · 更新 {{ fmtTime(detail.state.modify_time) }}
          </span>
          <t-popconfirm
            content="强制重新入队并重新跑完整流水线，确定？"
            @confirm="handleRejudge"
          >
            <t-button size="small" theme="primary" variant="outline">重判</t-button>
          </t-popconfirm>
        </t-space>
        <!-- AI 审阅总进度：五阶段完成度 + 进行中阶段 -->
        <div v-if="totalSteps > 0" class="detail-progress">
          <t-progress
            class="detail-progress-bar"
            :percentage="progressPercent"
            :color="detail.state?.status === 3 ? 'var(--td-success-color)' : 'var(--td-brand-color)'"
            size="small"
          />
          <span class="detail-meta">
            {{ doneSteps }}/{{ totalSteps }} 阶段完成{{ runningStage ? ` · 正在 ${runningStage}` : "" }}
          </span>
        </div>
      </div>
      <t-alert
        v-if="detail.state?.message"
        theme="danger"
        class="detail-alert"
        :message="detail.state.message"
      />

      <!-- 题面（折叠） -->
      <div class="detail-section">
        <div class="detail-section-head">
          <t-button
            size="small"
            variant="text"
            theme="primary"
            @click="statementOpen = !statementOpen"
          >
            {{ statementOpen ? "收起题面" : "展开题面" }}
          </t-button>
          <span class="detail-meta">
            时限 {{ detail.problem.time_limit }}ms · 内存 {{ detail.problem.memory_limit }}KB ·
            {{ detail.problem.judge_type === 1 ? "SPJ 特殊判题" : "普通比较判题" }}
          </span>
        </div>
        <div v-if="statementOpen" class="detail-statement">{{ detail.problem.description }}</div>
        <div v-if="(detail.problem.tag_names ?? []).length" class="detail-tags">
          <t-tag v-for="n in detail.problem.tag_names ?? []" :key="n" size="small" variant="outline">{{ n }}</t-tag>
        </div>
      </div>

      <t-row :gutter="[16, 16]">
        <!-- 主区：五类产出（各自展示「当前」或右侧栏选中的历史版本） -->
        <t-col :span="isMobile ? 12 : 8">
          <div class="detail-main">
            <div
              v-for="a in detail.annotations ?? []"
              :key="a.task_type"
              :ref="setCardRef(a.task_type)"
              class="detail-card"
              :class="{
                'detail-card-history': !view(a).isCurrent,
                'detail-card-rejected': view(a).review_status === 'rejected',
              }"
            >
              <div class="detail-card-head">
                <span class="detail-card-title">
                  {{ taskTypeText[a.task_type] || a.task_type }}
                  <t-tag v-if="!view(a).isCurrent" theme="warning" variant="light" size="small">历史版本</t-tag>
                </span>
                <t-space size="small" break-line>
                  <!-- 移动端：版本切换器（桌面端等价入口是右侧「历史评价」栏） -->
                  <t-select
                    v-if="isMobile && (a.history ?? []).length"
                    size="small"
                    class="detail-version-select"
                    :value="view(a).id"
                    @change="(id: string | number) => selectVersion(a, Number(id))"
                  >
                    <t-option v-for="v in versionsOf(a)" :key="v.id" :value="v.id" :label="versionLabel(v)" />
                  </t-select>
                  <t-button
                    v-if="!view(a).isCurrent"
                    size="small"
                    variant="text"
                    theme="primary"
                    @click="pickVersion(a.task_type, currentVersion(a))"
                  >
                    回到当前
                  </t-button>
                  <t-tag v-if="view(a).visibility" variant="outline" size="small">
                    {{ visibilityText[view(a).visibility] || view(a).visibility }}
                  </t-tag>
                  <t-tag v-if="view(a).source === 'human'" theme="default" variant="dark" size="small">人工</t-tag>
                  <t-tag v-if="view(a).review_status === 'rejected'" theme="danger" variant="light" size="small">
                    已驳回
                  </t-tag>
                  <span class="detail-meta">置信 {{ Math.round(view(a).confidence * 100) }}%</span>
                  <span class="detail-meta">{{ fmtTime(view(a).insert_time) }}</span>
                </t-space>
              </div>

              <div class="detail-card-body">
                <AnnotationCard :task-type="a.task_type" :payload="view(a).payload" :show-evidence="true" />
                <!-- 难度雷达图（移动端隐藏；图形跟随所选难度版本） -->
                <div
                  v-if="a.task_type === 'difficulty' && !isMobile"
                  :ref="setRadarRef"
                  class="detail-radar"
                />
              </div>
            </div>

            <div v-if="!detail.annotations.length" class="detail-empty">
              暂无产出标注（该题尚未完成 AI 审阅）
            </div>

            <!-- 调用账本 -->
            <div class="detail-section">
              <t-button size="small" variant="text" theme="primary" @click="callsOpen = !callsOpen">
                {{ callsOpen ? "收起调用账本" : `展开调用账本（${(detail.calls ?? []).length} 条）` }}
              </t-button>
              <template v-if="callsOpen">
                <div v-if="!(detail.calls ?? []).length" class="detail-empty">暂无调用记录</div>
                <div v-for="c in detail.calls ?? []" :key="c.id" class="call-row">
                  <div class="call-row-head">
                    <t-space size="small">
                      <t-tag theme="primary" variant="light">{{ stageText[c.stage] || c.stage }}</t-tag>
                      <t-tag :theme="callStatusTheme[c.status] || 'default'" variant="light">
